/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int data;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode(int val) { data = val; left = null, right = null }
 * }
 **/

class Solution {
    void zigZag(TreeNode root, List<List<Integer>> res) {
        Queue<TreeNode> a = new LinkedList<>();
        a.add(root);
        boolean swtch = true;
        Queue<TreeNode> b = new LinkedList<>();
        List<Integer> ls = new ArrayList<>();
        while(!a.isEmpty() || !b.isEmpty()) {
            if(swtch) {
                root = a.remove();
                if(root.left!=null) b.add(root.left);
                if(root.right!=null) b.add(root.right);
            } else {
                root = b.remove();
                if(root.left!=null) a.add(root.left);
                if(root.right!=null) a.add(root.right);
            }
            ls.add(root.data);
            if((a.isEmpty() && swtch) || (b.isEmpty() && !swtch)) {
               if(!swtch) Collections.reverse(ls); 
               res.add(ls); 
               ls = new ArrayList<>();
               swtch = !swtch;
            }
        }
    }
    public List<List<Integer>> zigzagLevelOrder(TreeNode root) {
       if(root==null) return null; 
       List<List<Integer>> res = new ArrayList<>();
       zigZag(root,res);
       return res;
    }
}
```

